import React from 'react';
import {createRoot} from 'react-dom/client';
import {LanguageProvider} from '../../components/LanguageProvider';
import {PostPreview} from '../../components/composer/PostPreview';
const platforms=['instagram','facebook','youtube','tiktok','pinterest'];
const picture=(color:string,label:string)=>'data:image/svg+xml,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="1000" viewBox="0 0 800 1000"><rect width="800" height="1000" fill="${color}"/><circle cx="620" cy="190" r="240" fill="#fff" opacity=".3"/><rect x="260" y="310" width="280" height="440" rx="40" fill="#fff"/><rect x="300" y="240" width="200" height="100" rx="18" fill="#244b43"/><text x="400" y="475" text-anchor="middle" fill="#244b43" font-family="Arial" font-size="30">MOOYAM</text><text x="400" y="530" text-anchor="middle" fill="#54796f" font-family="Arial" font-size="18">${label}</text><text x="400" y="880" text-anchor="middle" fill="#244b43" font-family="Arial" font-size="26">A little care. A fresh start.</text></svg>`);
const media=[{id:'one',mimeType:'image/jpeg',fileUrl:picture('#d5e9de','DAILY CARE'),originalAvailable:true},{id:'two',mimeType:'image/jpeg',fileUrl:picture('#ead9cd','NIGHT CARE'),originalAvailable:true}];
const maps=(v:any)=>Object.fromEntries(platforms.map(p=>[p,v]));
const shortCopy=location.hash==='#short';
createRoot(document.getElementById('root')!).render(<LanguageProvider><main style={{maxWidth:740,margin:'24px auto',padding:20}}><h1>平台预览 · 本地示例</h1><PostPreview {...{accounts:platforms.flatMap(platform=>[{id:platform,platform,displayName:platform==='tiktok'?'mooyamcosmetic':'Mooyam Cosmetics',status:'active',capabilities:{}},...(platform==='pinterest'?[{id:'pin-two',platform,displayName:'Second Brand',status:'active',capabilities:{}}]:[])]),texts:maps(shortCopy?'Daily care. #护肤 #SkinCare_2026':'A fresh start for your daily routine. 🌿\n让每一天的护肤，都简单一点。\n\n#护肤 #SkinCare_2026 ＃新品\nhttps://example.test/product#details\n\n'+('Discover your everyday essentials. '.repeat(5))),websites:maps(''),baseText:'',mediaByPlatform:maps(media),mediaSources:maps('shared'),pinterestSettingsByAccount:{pinterest:{title:'Daily care, beautifully simple'},'pin-two':{title:'Night care essentials'}},loading:false} as any}/></main></LanguageProvider>);
